// Isolated in-memory R2 transport for Python publisher integration; never contacts production.
const readline=require('node:readline');const {Bucket,input,sha,png}=require('./publication.cjs');
const {createPublicationService}=require('../../content/publication.cjs');const {verifyExtraction}=require('../../content/verification.cjs');
(async()=>{const bucket=new Bucket();await bucket.put('private/watchlist-v1.json',JSON.stringify({registry_revision:1,accepted_sources:[{uid:'544336675'}]}));const service=createPublicationService({bucket,probe:async()=>true});for await(const line of readline.createInterface({input:process.stdin})){try{const message=JSON.parse(line);if(message?.fixture){const x=input();x.proposal.visits[0].id=message.fixture;const bytes=png(message.seed||50),frame=x.sources.find(s=>s.kind==='frame');Object.assign(frame.payload,{sha256:sha(bytes),bytes:bytes.length});frame.sha256=sha(JSON.stringify(frame.payload));const privateFrames=[{sha256:sha(bytes),data:bytes.toString('base64')}];if(message.extra_frame){const other=png(80),copy=structuredClone(frame);copy.id='frame-extra';Object.assign(copy.payload,{timestamp_ms:22000,actual_timestamp_ms:22000,sha256:sha(other),bytes:other.length});copy.sha256=sha(JSON.stringify(copy.payload));x.sources.push(copy);privateFrames.push({sha256:sha(other),data:other.toString('base64')});}const r=await verifyExtraction(x);console.log(JSON.stringify({input:x,private_frames:privateFrames,records:r.records,documents:r.documents.map(d=>({sha256:d.sha256,data:Buffer.from(d.bytes).toString('base64')})),images:[{path:r.records[0].visit.screenshots[0].path,sha256:sha(bytes),mime_type:'image/png',bytes:bytes.length,width:64,height:64,data:bytes.toString('base64')}]}));}else if(message?.inspect)console.log(JSON.stringify({exists:!!await bucket.get(message.inspect)}));else if(message===null)console.log(JSON.stringify({current_publication:await service.current()}));else console.log(JSON.stringify(await service.operation(message)));}catch(e){console.log(JSON.stringify({transport_error:e.message}));}}})();
